cat > ~/.local/bin/deco-watch <<'PY'
#!/usr/bin/env python3
import gi, hashlib, json, os, shlex, subprocess, time
from pathlib import Path

gi.require_version("Atspi","2.0")
gi.require_version("Gtk","3.0")
gi.require_version("Gdk","3.0")
from gi.repository import Atspi, Gtk, Gdk

HOME=Path.home()
RUNTIME=Path(os.environ.get("XDG_RUNTIME_DIR",f"/run/user/{os.getuid()}"))
STATE=HOME/".local/state/deco"
STATE.mkdir(parents=True,exist_ok=True)
SEEN=STATE/"seen.json"
RUNROOT=RUNTIME/"deco"
RUNROOT.mkdir(parents=True,exist_ok=True)

AUTH="# DE-RUN"
APP="chatgpt-desktop-linux"

def log(x): print(x,flush=True)

def name(o):
    try:return o.get_name() or ""
    except:return ""

def role(o):
    try:return (o.get_role_name() or "").lower()
    except:return ""

def kids(o):
    out=[]
    try:
        for i in range(o.get_child_count()):
            c=o.get_child_at_index(i)
            if c is not None: out.append(c)
    except:pass
    return out

def walk(root):
    s=[root]
    while s:
        o=s.pop()
        yield o
        s.extend(reversed(kids(o)))

def desk(): return Atspi.get_desktop(0)

def chat():
    for a in kids(desk()):
        if name(a)==APP:return a
    raise RuntimeError("CHATGPT_APP_NOT_FOUND")

def term():
    for a in kids(desk()):
        if name(a)=="xfce4-terminal":
            for o in walk(a):
                if role(o)=="terminal":return o
    for a in kids(desk()):
        for o in walk(a):
            if role(o)=="terminal":return o
    raise RuntimeError("TERMINAL_NOT_FOUND")

def focused(o):
    try:return o.get_state_set().contains(Atspi.StateType.FOCUSED)
    except:return False

def focus(o):
    for _ in range(80):
        try:Atspi.Component.grab_focus(o)
        except:pass
        if focused(o):return
        time.sleep(.1)
    raise RuntimeError("FOCUS_FAIL")

def text(o):
    try:
        n=Atspi.Text.get_character_count(o)
        return Atspi.Text.get_text(o,0,n)
    except:return ""

def composer():
    fallback=[]
    for o in walk(chat()):
        try:
            editable=o.get_state_set().contains(Atspi.StateType.EDITABLE)
        except:
            editable=False
        if editable and role(o)=="entry" and name(o)=="Chat with ChatGPT":
            return o
        if editable and role(o) in ("entry","paragraph","text"):
            fallback.append(o)
    if fallback:return fallback[-1]
    raise RuntimeError("COMPOSER_NOT_FOUND")

def composer_text():
    c=composer()
    return "\n".join(x for x in [text(o) for o in walk(c)] if x).strip()

def boxes():
    out=[]
    for o in walk(chat()):
        if role(o)=="section":
            n=name(o)
            if n.startswith(AUTH+"\n") or n.strip()==AUTH:
                out.append(n)
    return out

CB=Gtk.Clipboard.get(Gdk.SELECTION_CLIPBOARD)

def clipset(s):
    CB.set_text(s,-1)
    CB.store()

def ykey(*args):
    env=dict(os.environ)
    for p in (
        RUNTIME/"de-ydotool.sock",
        RUNTIME/".ydotool_socket",
        RUNTIME/"ydotool.sock"
    ):
        if p.exists():
            env["YDOTOOL_SOCKET"]=str(p)
            break
    r=subprocess.run(["ydotool","key",*args],env=env)
    if r.returncode:
        raise RuntimeError(f"YDOTOOL_RC={r.returncode}")

def paste_terminal(cmd):
    focus(term())
    clipset(cmd)
    ykey("29:1","42:1","47:1","47:0","42:0","29:0")
    time.sleep(.15)
    ykey("28:1","28:0")

def run(payload,h):
    d=RUNROOT/h[:16]
    d.mkdir(parents=True,exist_ok=True)
    src=d/"payload.sh"
    out=d/"output.txt"
    rc=d/"exit"
    done=d/"done"

    src.write_text(payload)
    src.chmod(0o700)

    for p in (out,rc,done):
        try:p.unlink()
        except FileNotFoundError:pass

    cmd=(
        f"bash {shlex.quote(str(src))} 2>&1 | tee {shlex.quote(str(out))}; "
        f"rc=${{PIPESTATUS[0]}}; "
        f"echo \"$rc\" > {shlex.quote(str(rc))}; "
        f"touch {shlex.quote(str(done))}"
    )

    paste_terminal(cmd)

    limit=time.time()+3600
    while time.time()<limit:
        if done.exists() and rc.exists() and out.exists():break
        time.sleep(.25)
    else:
        raise RuntimeError("RUN_TIMEOUT")

    return int(rc.read_text().strip()),out.read_text(errors="replace")

def reduce_output(raw,rc,h):
    lines=raw.splitlines()
    try:
        a=max(i for i,x in enumerate(lines) if x.strip()=="DECO_SUMMARY_BEGIN")
        b=next(i for i in range(a+1,len(lines))
               if lines[i].strip()=="DECO_SUMMARY_END")
        body="\n".join(lines[a:b+1])
    except:
        body="\n".join(lines[-60:])

    return (
        "```text\n"
        "DECO_RESULT_BEGIN\n"
        f"TASK_SHA256={h}\n"
        f"EXIT={rc}\n"
        f"{body}\n"
        "DECO_RESULT_END\n"
        "```"
    )

def send(result):
    for _ in range(400):
        if composer_text()=="":
            break
        time.sleep(.25)
    else:
        raise RuntimeError("COMPOSER_BUSY")

    c=composer()
    focus(c)
    clipset(result)
    ykey("29:1","47:1","47:0","29:0")
    time.sleep(.6)

    if "DECO_RESULT_BEGIN" not in composer_text():
        raise RuntimeError("PASTE_VERIFY_FAIL")

    ykey("28:1","28:0")

def load_seen():
    try:return set(json.loads(SEEN.read_text()))
    except:return set()

def save_seen(s):
    SEEN.write_text(json.dumps(sorted(s),indent=2)+"\n")

seen=load_seen()

for b in boxes():
    seen.add(hashlib.sha256(b.encode()).hexdigest())
save_seen(seen)

log("DECO_SUMMARY_BEGIN")
log("STAGE=DECO2_ARM")
log("CHATGPT_APP=PASS")
log("COMPOSER=PASS")
log("TERMINAL=PASS")
log("SERVICE_MODE=FOREGROUND_DAEMON")
log("STATUS=PASS")
log("DECO_ARMED=YES")
log("NEXT=WAIT_FOR_NEW_DE_RUN_BLOCK")
log("DECO_SUMMARY_END")

while True:
    try:
        for payload in boxes():
            h=hashlib.sha256(payload.encode()).hexdigest()
            if h in seen:continue

            seen.add(h)
            save_seen(seen)

            log(f"TASK={h}")
            rc,out=run(payload,h)
            send(reduce_output(out,rc,h))
            log("DECO_CYCLE=PASS")

        time.sleep(.35)

    except Exception as e:
        log(f"DECO_ERROR={type(e).__name__}:{e}")
        time.sleep(1)
PY

chmod +x ~/.local/bin/deco-watch
systemctl --user disable --now de-bridge-watch.service deco-watch.service 2>/dev/null || true
pkill -f "$HOME/.local/bin/deco-watch" 2>/dev/null || true

nohup ~/.local/bin/deco-watch \
  > ~/.local/state/deco/watch.log 2>&1 &

echo $! > ~/.local/state/deco/watch.pid
sleep 2

echo "DECO_SUMMARY_BEGIN"
tail -20 ~/.local/state/deco/watch.log
echo "PID=$(cat ~/.local/state/deco/watch.pid)"
echo "DECO_SUMMARY_END"
```

