from pathlib import Path
import ast
import sys

p=Path(sys.argv[1])
s=p.read_text()

def replace_func(src,name,replacement):
    tree=ast.parse(src)
    node=next(
        (
            x for x in tree.body
            if isinstance(x,(ast.FunctionDef,ast.AsyncFunctionDef))
            and x.name==name
        ),
        None
    )
    if node is None:
        raise SystemExit(f"FUNCTION_NOT_FOUND:{name}")

    lines=src.splitlines(keepends=True)
    lines[node.lineno-1:node.end_lineno]=[
        replacement.rstrip()+"\n\n"
    ]
    return "".join(lines)

