def composer_text():
    c=composer()

    # Chromium/Electron exposes the outer composer as an editable Entry,
    # while the actual user text lives in its descendant Paragraph.
    for o in walk(c):
        if role(o)=="paragraph":
            tx=text(o)
            if tx:
                return tx

    tx=text(c)
    return tx or ""


def composer_focused(c):
    try:
        return c.get_state_set().contains(Atspi.StateType.FOCUSED)
    except:
