        if b":" in line:
            k, v = line.split(b":", 1)
            headers[k.strip().lower()] = v.strip()

    actual = headers.get(b"sec-websocket-accept", b"").decode()
    if actual != expected:
        raise RuntimeError("websocket accept mismatch")

    return s, bytearray(rest)


def recv_exact(sock, pending, n):
    while len(pending) < n:
        chunk = sock.recv(65536)
        if not chunk:
            raise RuntimeError("websocket closed")
        pending.extend(chunk)

    out = bytes(pending[:n])
    del pending[:n]
    return out


def ws_send_text(sock, text):
    payload = text.encode()
    n = len(payload)

    first = 0x81
    maskbit = 0x80
    mask = os.urandom(4)

    if n < 126:
        header = bytes([first, maskbit | n])
    elif n < 65536:
        header = bytes([first, maskbit | 126]) + struct.pack("!H", n)
    else:
        header = bytes([first, maskbit | 127]) + struct.pack("!Q", n)

    masked = bytes(
        b ^ mask[i % 4]
        for i, b in enumerate(payload)
    )

    sock.sendall(header + mask + masked)


def ws_recv_text(sock, pending):
    fragments = []

    while True:
        h = recv_exact(sock, pending, 2)
        b1, b2 = h

        fin = bool(b1 & 0x80)
        opcode = b1 & 0x0f
        masked = bool(b2 & 0x80)
        n = b2 & 0x7f

        if n == 126:
            n = struct.unpack("!H", recv_exact(sock, pending, 2))[0]
        elif n == 127:
            n = struct.unpack("!Q", recv_exact(sock, pending, 8))[0]

        mask = recv_exact(sock, pending, 4) if masked else None
        payload = recv_exact(sock, pending, n)

