          if (settled.split("\\n")[0] !== "# DE-RUN")
            return;

          if (settled.length <= 8)
            return;

          emitted.add(pre);

          decoNative(JSON.stringify({{
            kind:"AUTHORIZED_CODE_SETTLED",
            payload:settled,
            chars:settled.length
          }}));
        }}, {SETTLE_MS});

        timers.set(pre, timer);
      }};

      const inspect = node => {{
        if (!node)
          return;

        if (node.nodeType === 1) {{
          if (node.matches && node.matches("pre"))
            schedule(node);

          if (node.closest)
            schedule(node.closest("pre"));

          if (node.querySelectorAll)
            node.querySelectorAll("pre").forEach(schedule);
        }}

        if (node.parentElement && node.parentElement.closest)
          schedule(node.parentElement.closest("pre"));
      }};

      window.__DECO_NATIVE_OBSERVER__ =
        new MutationObserver(records => {{
          for (const record of records) {{
            inspect(record.target);

            for (const node of record.addedNodes)
              inspect(node);
          }}
        }});

      window.__DECO_NATIVE_OBSERVER__.observe(
        document.body,
        {{
          subtree:true,
          childList:true,
          characterData:true
        }}
      );

      return {{
        armed:true,
        baseline:document.querySelectorAll("pre").length,
        settleMs:{SETTLE_MS}
      }};
    }})()
    """

    reply = cdp.evaluate(expr)

    value = (
        reply.get("result", {})
        .get("result", {})
        .get("value", {})
    )

    if not value.get("armed"):
        raise RuntimeError("OBSERVER_ARM_FAIL")

    log(
        "ARMED "
        f"baseline={value.get('baseline')} "
        f"settle_ms={SETTLE_MS}"
    )


def handle_pending(cdp):
    if not PENDING.exists():
        return True

    try:
        pending = json.loads(PENDING.read_text())
        digest = pending["digest"]
        result = pending["result"]
    except Exception:
        log("PENDING_PARSE_FAIL")
        return False

    outcome = return_result(cdp, result)
    status = outcome.get("status", "UNKNOWN")
    log(f"PENDING_RETURN status={status}")

    if status in {
        "SEND_CONFIRMED",
        "PASTE_COMMITTED_SEND_UNCONFIRMED"
    }:
        mark_seen(digest)
        clear_pending()
        return True

    return False


def main():
    log("START")

    cdp = CDP()
    log("CDP_CONNECTED")

    if not handle_pending(cdp):
        log("BLOCKED_PENDING_RETURN")
        return 2

    arm_observer(cdp)

    while True:
        msg = json.loads(cdp.ws.recv_text())

        if msg.get("method") != "Runtime.bindingCalled":
            continue

        params = msg.get("params", {})

        if params.get("name") != "decoNative":
            continue

        try:
            event = json.loads(params.get("payload", "{}"))
        except Exception:
            log("EVENT_JSON_FAIL")
            continue

        if event.get("kind") != "AUTHORIZED_CODE_SETTLED":
            continue

        payload = event.get("payload", "")

        if not isinstance(payload, str):
            log("PAYLOAD_TYPE_FAIL")
            continue

        if len(payload.encode()) > MAX_PAYLOAD:
            log("PAYLOAD_GATE=FAIL_TOO_LARGE")
            continue

        lines = payload.replace("\r\n", "\n").replace("\r", "\n").splitlines()

        if not lines or lines[0] != "# DE-RUN":
            log("PAYLOAD_GATE=FAIL_AUTH")
            continue

        digest = hashlib.sha256(payload.encode()).hexdigest()

        if digest in load_seen():
            log(f"DUPLICATE_SKIP sha256={digest}")
            continue

        log(
            f"PAYLOAD_GATE=PASS sha256={digest} "
            f"chars={len(payload)}"
        )

        result = execute_payload(payload, digest)
        save_pending(digest, result)

        outcome = return_result(cdp, result)
        status = outcome.get("status", "UNKNOWN")

        log(f"RETURN status={status}")

        if status in {
            "SEND_CONFIRMED",
            "PASTE_COMMITTED_SEND_UNCONFIRMED"
        }:
            mark_seen(digest)
            clear_pending()

        elif status == "COMPOSER_OCCUPIED":
            log("RETURN_BLOCKED=COMPOSER_OCCUPIED")
            return 3

        else:
            log("RETURN_BLOCKED=" + status)
            return 4


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except KeyboardInterrupt:
        log("STOP=KEYBOARD_INTERRUPT")
        raise SystemExit(130)
    except Exception as exc:
        log(
            "FATAL="
            + type(exc).__name__
            + ":"
            + str(exc)
        )
        raise
